INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/01/31 12:00:00", 62, 3.414, 1, "カリン", 0.0, "2030/01/01 14:59:59", "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 1, -416.5, 2, 1, 190801, 1000001);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/01/31 12:00:00", 62, 3.099, 1, "カリン", 0.0, "2030/01/01 14:59:59", "ミッションをクリアして、\n報酬をゲットしましょう！", 1, -416.5, 2, 2, 190801, 1000002);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/01/31 12:00:00", 63, 2.801, 1, "カリン", 0.0, "2030/01/01 14:59:59", "受け取ることができる\n報酬があるようです\n確認してみてください", 1, -416.5, 2, 3, 190801, 1000003);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/01/31 12:00:00", 63, 0.0, 2, "カリン", 0.0, "2030/01/01 14:59:59", "報酬がもらえますよ！\nチェックしてみてください", 1, -416.5, 2, 4, 190801, 1000004);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/01/31 12:00:00", 64, 2.12, 2, "カリン", 0.0, "2030/01/01 14:59:59", "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 1, -363.0, 1, 5, 190801, 1000005);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/01/31 12:00:00", 64, 1.68, 1, "カリン", 0.0, "2030/01/01 14:59:59", "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 1, -363.0, 2, 6, 190801, 1000006);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/01/31 12:00:00", 64, 2.33, 2, "カリン", 0.0, "2030/01/01 14:59:59", "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 1, -363.0, 1, 7, 190801, 1000007);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/01/31 12:00:00", 61, 5.18, 3, "ラビリスタ", -6.0, "2030/01/01 14:59:59", "今度の敵は、アタシにとっても\n放ってはおけない存在だ\n少年、アタシも全力で行くからさ\n一緒に守ろう、この世界を", 10201, -285.0, 7, 101, 133701, 1020101);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/01/31 12:00:00", 61, 8.77, 1, "クリスティーナ", -2.0, "2030/01/01 14:59:59", "退屈の吹き飛ぶような\n戦いの気配がするなぁ坊や\nさっさとワタシをそこへ連れてゆけ\n世界も守ってやるさ、ついでにな", 10201, -285.0, 2, 201, 133901, 1020102);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/01/31 12:00:00", 61, 15.5, 6, "ネネカ", 0.0, "2030/01/01 14:59:59", "おや、私の力が必要……と？\nグレゴールが手伝うそうですよ\n私は戦わないのか、という顔ですね\n……考えておきます", 10201, -285.0, 1, 301, 133801, 1020103);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/02/28 12:00:00", 61, 9.061, 2, "ランファ", 0.0, "2030/01/01 14:59:59", "わたしだけの歌…\n一緒に、探してくれる…？\nあなたがいれば…\nもっとがんばれるから…", 10202, -285.0, 5, 101, 134301, 1020201);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/02/28 12:00:00", 61, 7.699, 1, "チカ", 0.0, "2030/01/01 14:59:59", "同じ唱喚士として、仲間として\n私にできることをします\n…これも、あなたが\n背中を押してくれたおかげですよ", 10202, -285.0, 2, 201, 134401, 1020202);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/03/31 12:00:00", 61, 8.595, 1, "アオイ", 0.0, "2030/01/01 14:59:59", "世界の平和が私とクローチェさんに\nかかってるんですよね？\nぼっちには過大すぎる期待ですけど\nふ、二人でなら背負ってみせます！", 10203, -285.0, 2, 101, 134601, 1020301);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/03/31 12:00:00", 61, 7.758, 1, "クローチェ", 0.0, "2030/01/01 14:59:59", "新しく手に入れたこの翼で…\nナイトさんがどこにいたって\nわたし、駆けつけちゃいますよっ！\nクローチェ・エアリアル発進ですっ", 10203, -285.0, 2, 201, 134501, 1020302);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/04/30 12:00:00", 61, 7.0, 2, "ルイズマリー", 0.0, "2030/01/01 14:59:59", "今日はダーリンとの初デート♪\n二人でショッピングして、その後は\n…って私、指名手配されてる！？\nちょ、た…助けてダーリン～！！", 10204, -285.0, 6, 101, 132302, 1020401);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/04/30 12:00:00", 61, 7.904, 1, "イロハ", 0.0, "2030/01/01 14:59:59", "ルイちゃんのおばあちゃん優しくて\nいつもにこにこで、イロハ大好き♪\nでも一番好きなのは、角がすっごく\n大きくてかっこいいとこなんだ～♪", 10204, -285.0, 2, 201, 132402, 1020402);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/04/30 12:00:00", 61, 8.487, 4, "ソノ", 0.0, "2030/01/01 14:59:59", "ノゾミちゃんのおかげで売上が安定\nしてきたのに、臨時休業、痛すぎる\n…ま、ルイちゃんのために\n一肌脱ぐか。行くよイロハ～", 10204, -285.0, 2, 301, 132502, 1020403);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/05/31 12:00:00", 61, 8.763, 1, "カノン", 0.0, "2030/01/01 14:59:59", "ヲ～ッホッホ♪\nあたくし様と同じお空気を吸える\nお幸運を噛みしめなさいですわ～♪\nヲ～ッホッホッホ～♪", 10205, -285.0, 2, 101, 134901, 1020502);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/05/31 12:00:00", 61, 6.417, 1, "ツムギ", 0.0, "2030/01/01 14:59:59", "いきますよ騎士さん！\nカノンさんと力を合わせて…力を…\n…本当にあの人なんなんです？\nこれまでになく不安なんですけど！", 10205, -285.0, 3, 201, 134801, 1020503);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/06/30 12:00:00", 61, 10.335, 3, "エリス", 0.0, "2030/01/01 14:59:59", "『願いが叶う海岸』か…怪しい\nだというのに、阿賀斗紫布菜たちは\n呑気に戯れている…見ていられない\n騎士クンは、わたしが守ってみせる", 10206, -285.0, 7, 101, 135001, 1020601);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/06/30 12:00:00", 61, 6.281, 2, "シェフィ", 0.0, "2030/01/01 14:59:59", "せっかくの夏休みなんだし\nたまにはビーチでゆっくりしましょ\n…え、もしかしてこの夏もあんまり\n休めなかったりする感じなの？", 10206, -285.0, 4, 201, 135101, 1020602);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/06/30 12:00:00", 61, 12.244, 1, "プレシア", 0.0, "2030/01/01 14:59:59", "いっぱい。たべて\nおおきく。なると\nせーぎ。まもれる。はず\nお兄。いっしょに。スイカ。たべよ", 10206, -285.0, 2, 301, 135201, 1020603);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/07/31 12:00:00", 61, 6.339, 2, "クリア", 0.0, "2030/01/01 14:59:59", "ひと夏の冒険のはじまりです！\nアネモネさんも楽しんでくれたら\n…できれば、もう少し\n仲良くなれたらうれしいな…", 10207, -285.0, 8, 101, 135301, 1020701);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/07/31 12:00:00", 61, 8.184, 7, "アネモネ", 0.0, "2030/01/01 14:59:59", "─幻の花…\n本当にあるのか謎─ですけど\n探すくらいは、\n付き合ってもいいです", 10207, -285.0, 9, 201, 135401, 1020702);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/08/31 12:00:00", 61, 3.906, 9, "アイラ", 0.0, "2030/01/01 14:59:59", "あははっ！　笑う門には福来る！\n笑ってればきっと、複製世界にも\n未来はやってくるって信じてる！\nそうだよね、シナツちゃん！", 10208, -285.0, 2, 101, 129101, 1020801);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/08/31 12:00:00", 61, 14.465, 1, "シナツ", 0.0, "2030/01/01 14:59:59", "繰り返されるリセットの先の未来\n何度願っても手に入らなかった未来\n…でも、私は諦めない。絶対にだ\nキミも同じだろ…アイラ？", 10208, -285.0, 2, 201, 129201, 1020802);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/08/31 12:00:00", 61, 8.662, 4, "ヒヨリ", 0.0, "2030/01/01 14:59:59", "アイラの世界のみんなも、\n一生懸命生きてるんだ…！\n…なのに、世界の危機だなんて！\nあたし、絶対、絶対力になるよ！", 10208, -285.0, 3, 301, 100101, 1020803);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/08/31 12:00:00", 61, 10.915, 1, "レイ", 0.0, "2030/01/01 14:59:59", "シナツ…もう一人の私\n彼女が大切にしている世界を\n絶対に終わらせはしない…！\n彼女と笑い合える未来のために！", 10208, -285.0, 3, 401, 100301, 1020804);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/09/30 12:00:00", 61, 6.042, 1, "ユキノ", 0.0, "2030/01/01 14:59:59", "あ、ど、ども…\nあ、あんま見ねぇでくれっと\nその、恥ずかしくて…\n体が熱くなって、溶けちまう…", 10209, -285.0, 7, 101, 135802, 1020901);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/09/30 12:00:00", 61, 9.402, 4, "サツキ", 0.0, "2030/01/01 14:59:59", "なんで俺が幽霊に…意味不明だ\nこれじゃ死んでも死にきれねェ\n悪ィがこれも何かの縁だ、\nよろしく頼むぜ騎士公", 10209, -285.0, 1, 201, 135903, 1020902);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/09/30 12:00:00", 61, 8.16, 8, "ルルィ", 0.0, "2030/01/01 14:59:59", "う、うじゅる…\nサツキ姉しゃまを助けるためにも\nまずは、腹ごしらえでしゅね…！\nタコ焼き、召し上がってくだしゃい", 10209, -285.0, 1, 301, 136902, 1020903);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/10/31 12:00:00", 61, 5.0, 3, "カスミ", 0.0, "2030/01/01 14:59:59", "ひさしぶりのジオ・ゲヘナ\n歓迎パーティーで起きた殺人事件！\nランドソルの名探偵の名にかけて\n解き明かしてみせようじゃないか！", 10210, -285.0, 2, 101, 137401, 1021001);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/10/31 12:00:00", 61, 8.12, 4, "アラクネ", 0.0, "2030/01/01 14:59:59", "…わたしはどこの誰なのでしょう\nどこから来てどこへ行くのでしょう\nこの事件の真相が分かれば、\n何かが掴めるような気がいたします", 10210, -285.0, 1, 201, 136001, 1021002);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/10/31 12:00:00", 61, 6.386, 4, "ナーナ", 0.0, "2030/01/01 14:59:59", "ナーナ、すいりとかろんぱとか、\nむずかしくてわかんないけど…\nお友だちとドーナツのためならっ\nせーいっぱいがんばるよっ！", 10210, -285.0, 2, 301, 136202, 1021003);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/11/30 12:00:00", 61, 7.438, 3, "ユイ", 0.0, "2030/01/01 14:59:59", "騎士クンに想いを伝えたい…だから\nミソラちゃん、わたしがんばるね！\n…あれ？　わたし、なんでこんなに\n必死になってるんだろう…？", 10211, -285.0, 4, 101, 136402, 1021101);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/11/30 12:00:00", 61, 8.35, 1, "ミソラ", 0.0, "2030/01/01 14:59:59", "騎士さんとのデートはわたしに\nお任せです★　なのでユイさんは\n安心して計画に専念して…たくさん\nドキドキしちゃってくださいね", 10211, -285.0, 5, 201, 136302, 1021102);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/12/31 12:00:00", 61, 5.0, 1, "シズル", 0.0, "2030/01/01 14:59:59", "新しい年がやってくるね！\nお正月の料理も飾りつけも、\nお姉ちゃんにお任せだよ♪\nみんなで楽しく新年を迎えよう！", 10212, -285.0, 2, 101, 136501, 1021201);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/12/31 12:00:00", 61, 5.25, 1, "リノ", 0.0, "2030/01/01 14:59:59", "おうちの掃除もトラブルも、 \n世界を揺るがす大ピンチも！\n今年のことは今年のうちに \nサッサと片付けちゃいますっ！", 10212, -285.0, 2, 201, 137902, 1021202);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2025/12/31 12:00:00", 61, 7.5, 1, "ラビリスタ", 0.0, "2030/01/01 14:59:59", "年の瀬はギルドマスターも\nつい駆け回っちゃう忙しい時期だ！\n一年いろいろあったけど\nお互いイイ年を迎えよう、少年！", 10212, -285.0, 2, 301, 106801, 1021203);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/01/31 12:00:00", 61, 8.204, 1, "ライラエル", 0.0, "2030/01/01 14:59:59", "漂う異国の料理の香り…それだけで\n世界中を旅した気分に浸れますね\nふふ、ほらクローチェ\nあまりはしゃぎすぎないように…♪", 10213, -285.0, 2, 101, 126501, 1021301);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/01/31 12:00:00", 61, 7.176, 1, "ネフィ＝ネラ", 0.0, "2030/01/01 14:59:59", "異界の姫君と煮炊きにて競い合う…\n感奮興起、いとをかし\n華やかなる祭典と相成るよう、一肌\n脱がせていただきとう存じまする", 10213, -285.0, 2, 201, 129701, 1021302);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/01/31 12:00:00", 61, 8.602, 1, "ヴァイオレット", 0.0, "2030/01/01 14:59:59", "『ビストロプリンセス』のために\n料理の特訓を重ねてまいりました\nこの料理で騎士様の…い、いえ\n皆様の心とお腹を満たしますわ！", 10213, -285.0, 5, 301, 133101, 1021303);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/02/06 12:00:00", 61, 10.14, 1, "ライラエル", 0.0, "2030/01/01 14:59:59", "多様な味わいが織りなすハーモニー\nそれこそが我が国の矜持です\nもしもそれを乱すようであれば\nわたしも優しくはありませんよ？", 10213, -285.0, 3, 102, 138101, 1021304);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/02/06 12:00:00", 61, 10.152, 1, "ネフィ＝ネラ", 0.0, "2030/01/01 14:59:59", "煉獄の穢土にてひと際輝く民草の心\n此れを守護りまするがわっちの責務\n如何な困難待ち受けようと\n不退転の矜持に揺らぎはありんせん", 10213, -285.0, 7, 202, 138201, 1021305);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/02/06 12:00:00", 61, 9.688, 4, "ヴァイオレット", 0.0, "2030/01/01 14:59:59", "裏世界の皆様は危機を脱し、\n残るはランドソルの皆様のみ…\n彼らを救い出すために、どうか…\nお立ち下さいペコリーヌ姫…！", 10213, -285.0, 3, 302, 138001, 1021306);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/02/12 12:00:00", 61, 5.928, 2, "ペコリーヌ", 0.0, "2030/01/01 14:59:59", "みなさん、お待たせしちゃいました\nペコリーヌ、完全復活です☆\nみなさんの食卓を守るため\nもう二度と、わたしはめげません！", 10213, -285.0, 1, 401, 138301, 1021307);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/02/28 12:00:00", 61, 9.19, 4, "ワカナ", 0.0, "2030/01/01 14:59:59", "成行きで参加することになっちゃっ\nた尻相撲大会。ううっ、恥ずかしい\nけどやるしかないよね。…騎士さん\nいっぱい応援してくださいね？", 10214, -285.0, 2, 101, 138702, 1021401);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/02/28 12:00:00", 61, 8.724, 1, "シオリ", 0.0, "2030/01/01 14:59:59", "「お姉ちゃんを守れる自分になる」\nあの日の約束、今こそ果たしてみせ\nます。例えお姉ちゃんに背くことに\nなっても。例えそれが尻相撲でも！", 10214, -285.0, 3, 201, 138802, 1021402);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/03/31 12:00:00", 61, 7.758, 4, "グレイス", 0.0, "2030/01/01 14:59:59", "私がへんたいふしんしゃさんって…\nただ生きているだけなのに、ひどい\n…まぁ死んでるんですけど…とか\n言ってる暇もない感じですか？", 10215, -285.0, 1, 101, 138902, 1021501);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/03/31 12:00:00", 61, 6.375, 6, "キョウカ", 0.0, "2030/01/01 14:59:59", "あの、助けてください！\n私がへんたいふしんしゃさんに\nなっちゃったみたいなんです…！\nどういう意味かは私もわかりません", 10215, -285.0, 4, 201, 139002, 1021502);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/03/31 12:00:00", 61, 6.173, 6, "ルルィ", 0.0, "2030/01/01 14:59:59", "ましゃか、グレイス姉しゃまたちが\nへんたいふしんしゃさんだなんて…\n騎士しゃん。あたちたちも協力ちて\n二人の破滅エンドを回避ちましょう", 10215, -285.0, 1, 301, 136902, 1021503);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/04/30 12:00:00", 61, 4.202, 6, "ミホ", 0.0, "2030/01/01 14:59:59", "違う世界に来ちゃうし、\n驚きの連続だけど…\nわたしも精いっぱい頑張ります！\nアストルムのみんなと一緒に！", 10216, -285.0, 2, 101, 139202, 1021601);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/04/30 12:00:00", 61, 2.842, 6, "マホ", 0.0, "2030/01/01 14:59:59", "想定外の事象が発生したな…だが\nいかなる苦境も切り抜けてみせる\nいつもの自分とは違う姿になっても\nわたしはわたし、西住流だ", 10216, -285.0, 1, 201, 139302, 1021602);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/04/30 12:00:00", 61, 4.598, 4, "エリカ", 0.0, "2030/01/01 14:59:59", "何でこんなことになっているのか\n全然わからないけど、迷ってる暇は\nないわ。黒森峰の次期隊長として、\n前進あるのみ！　これも戦車道よ！", 10216, -285.0, 1, 301, 139402, 1021603);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/05/31 12:00:00", 61, 6.533, 4, "リリ", 0.0, "2030/01/01 14:59:59", "わたくしたちの悲願は、ロストさせ\nてしまった方々をお助けすること…\nそのためなら、どのような辛苦にも\n耐え抜いてみせます…！", 10217, -285.0, 3, 101, 125802, 1021701);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/05/31 12:00:00", 61, 5.0, 3, "プレシア", 0.0, "2030/01/01 14:59:59", "みんなも。せーぎも。\nクリアも。パパ、も。\nぜったい、たすける。\nみててね。お兄。", 10217, -285.0, 3, 301, 126102, 1021702);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/05/31 12:00:00", 61, 5.214, 3, "クリア", 0.0, "2030/01/01 14:59:59", "癒しの力を使うこと…\nもう、ためらいません！\nモネちゃんやお兄さん…\nみんなに許してもらうためにも！", 10217, -285.0, 4, 201, 126002, 1021703);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/05/31 12:00:00", 61, 8.781, 1, "リリ", 0.0, "2030/01/01 14:59:59", "ヴァルキュリア─皆様を助けたい\nという願いを、力にできるのなら…\nわたくしたちは、きっと誰にも\n負けません！　一意専心です…！", 10217, -285.0, 3, 102, 139501, 1021704);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/05/31 12:00:00", 61, 6.529, 2, "クリア", 0.0, "2030/01/01 14:59:59", "このヴァルキュリアって職業、\nまるで天使みたいな格好ですよね\nうーん…『聖女』ちゃんって\n呼ばれるよりは、マシかな？", 10217, -285.0, 1, 202, 139601, 1021705);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/05/31 12:00:00", 61, 3.195, 3, "プレシア", 0.0, "2030/01/01 14:59:59", "ばるきり。もーど。\nはね。まっしろ。\nはっぴーちゃんと。おなじ。\nいいかんじ。", 10217, -285.0, 2, 302, 139701, 1021706);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/06/30 12:00:00", 61, 12.43, 2, "ルイズマリー", 0.0, "2030/01/01 14:59:59", "ダーリンと一緒に南の島で\nリゾート開発なんて夢みたい♪\nああ…幸せ、最高の夏だわ…\n触れたら爆発さえしなければ～…っ", 10218, -285.0, 3, 101, 139902, 1021801);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/06/30 12:00:00", 61, 6.35, 2, "クレジッタ", 0.0, "2030/01/01 14:59:59", "青い空、白い雲…無人島リゾートで\n大儲けですわ～♪　こらこらそこ、\nイチャついてるんじゃないですのよ\n触れたらドカンですわよ、ドカン！", 10218, -285.0, 3, 201, 140001, 1021802);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/07/31 12:00:00", 61, 10.23, 1, "フブキ", 0.0, "2030/01/01 14:59:59", "みんなはかわいいぼくを見られて、\nぼくはみんなからラヴをもらう♡\n最高のウィンウィンだよね、これ♡\nで、最後はお兄さんをドレーに…♡", 10219, -285.0, 5, 101, 140102, 1021901);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/07/31 12:00:00", 61, 5.584, 1, "ヴァンピィ", 0.0, "2030/01/01 14:59:59", "けんぞくとたくさん遊ぶためにも、\nみんなからラヴをもらわなくちゃ♪\nバズっちゃおー作戦、\n一緒に考えてね！　けんぞくぅ♪", 10219, -285.0, 2, 201, 140201, 1021902);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/08/31 12:00:00", 61, 2.8, 6, "クローチェ", 0.0, "2030/01/01 14:59:59", "あっちもこっちも、\nエマージェンシーですっ！\nみんなのピンチを助けるために\n行きましょうっ、ナイトさんっ！", 10220, -285.0, 3, 201, 126401, 1022001);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/08/31 12:00:00", 61, 8.9, 4, "ヴルム", 0.0, "2030/01/01 14:59:59", "みんながあたしを許してくれても…\nあたしは、あたしを許せない\nそれでも…この世界が危ないなら\n迷ってなんか、いられない", 10220, -285.0, 3, 101, 127802, 1022002);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/08/31 12:00:00", 61, 4.49, 2, "クローチェ", 0.0, "2030/01/01 14:59:59", "クローチェ、サブマリンモードっ\n換装完了ですっ♪\nどんな荒波も、ナイトさんとなら\n越えちゃいますからっ！", 10220, -285.0, 1, 202, 140602, 1022003);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/08/31 12:00:00", 61, 9.42, 1, "ヴルム", 0.0, "2030/01/01 14:59:59", "偽物でも、創り物でもいい\nあたしの中にある気持ちは、\nあたしの本物だから\n今度こそ、この力で守ってみせる", 10220, -285.0, 3, 102, 140501, 1022004);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/08/31 12:00:00", 61, 7.0, 4, "リーザ", 0.0, "2030/01/01 14:59:59", "世界と向き合うなんてこと…\n私には、わからない\nそれでも、受けた借りは\nちゃんと返さないとね", 10220, -285.0, 1, 301, 140402, 1022005);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/04/10 12:00:00", 62, 3.414, 1, "カリン", 0.0, "2030/01/01 14:59:59", "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 2, -416.5, 2, 1, 190805, 2000001);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/04/10 12:00:00", 62, 3.099, 1, "カリン", 0.0, "2030/01/01 14:59:59", "ミッションをクリアして、\n報酬をゲットしましょう！", 2, -416.5, 2, 2, 190805, 2000002);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/04/10 12:00:00", 63, 2.801, 1, "カリン", 0.0, "2030/01/01 14:59:59", "受け取ることができる\n報酬があるようです\n確認してみてください", 2, -416.5, 2, 3, 190805, 2000003);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/04/10 12:00:00", 63, 0.0, 2, "カリン", 0.0, "2030/01/01 14:59:59", "報酬がもらえますよ！\nチェックしてみてください", 2, -416.5, 2, 4, 190805, 2000004);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/04/10 12:00:00", 64, 2.12, 2, "カリン", 0.0, "2030/01/01 14:59:59", "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 2, -363.0, 1, 5, 190805, 2000005);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/04/10 12:00:00", 64, 1.68, 1, "カリン", 0.0, "2030/01/01 14:59:59", "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 2, -363.0, 2, 6, 190805, 2000006);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2026/04/10 12:00:00", 64, 2.33, 2, "カリン", 0.0, "2030/01/01 14:59:59", "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 2, -363.0, 1, 7, 190805, 2000007);
